// Precompiles the JSON-schema validators with Ajv's standalone code
// generation so the bundle contains plain validation functions instead of
// compiling schemas at runtime. Runtime compilation uses new Function(),
// which browsers block on pages served with a Content-Security-Policy
// whose script-src lacks 'unsafe-eval' (e.g. pkic.org) — the widget would
// crash before customElements.define() ever ran.
//
// Output (git-ignored, regenerated by the pre<build|start|test> hooks):
//   src/generated/validators-draft07.js / .d.ts
//   src/generated/validators-2020.js    / .d.ts
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import Ajv from "ajv";
import Ajv2020 from "ajv/dist/2020.js";
import standaloneCode from "ajv/dist/standalone/index.js";
import addFormats from "ajv-formats";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const readSchema = (name) =>
  JSON.parse(readFileSync(join(root, "src/public", name), "utf8"));

const outDir = join(root, "src/generated");
mkdirSync(outDir, { recursive: true });

const HEADER =
  "// Generated by scripts/generate-validators.mjs — do not edit.\n";

// Options mirror the previous runtime instances in yamlParser.ts.
const options = { allErrors: true, strict: false, code: { source: true } };

const emit = (AjvClass, schemas, exports, outBase) => {
  const ajv = new AjvClass(options);
  addFormats(ajv);
  for (const [key, schema] of Object.entries(schemas)) {
    ajv.addSchema(schema, key);
  }
  const code = standaloneCode(ajv, exports);
  writeFileSync(join(outDir, `${outBase}.js`), HEADER + code);
  const dts =
    HEADER +
    'import type { ValidateFunction } from "ajv";\n' +
    Object.keys(exports)
      .map((name) => `export declare const ${name}: ValidateFunction;\n`)
      .join("");
  writeFileSync(join(outDir, `${outBase}.d.ts`), dts);
};

emit(
  Ajv,
  {
    "model-1.0.0": readSchema("pkimm-model.schema-1.0.0.json"),
    "model-2.0.0": readSchema("pkimm-model.schema-2.0.0.json"),
    "references-1.0.0": readSchema("pkimm-references.schema-1.0.0.json"),
  },
  {
    validateModel100: "model-1.0.0",
    validateModel200: "model-2.0.0",
    validateReferences100: "references-1.0.0",
  },
  "validators-draft07",
);

emit(
  Ajv2020,
  {
    "extension-1.0.0": readSchema("extension.schema-1.0.0.json"),
    "pqcmm-model-1.0.0": readSchema("pqcmm-model.schema-1.0.0.json"),
    "pqcmm-assessment-1.0.0": readSchema("pqcmm-assessment.schema-1.0.0.json"),
  },
  {
    validateExtension100: "extension-1.0.0",
    validatePqcmmModel100: "pqcmm-model-1.0.0",
    validatePqcmmAssessment100: "pqcmm-assessment-1.0.0",
  },
  "validators-2020",
);

console.log("Generated src/generated/validators-{draft07,2020}.{js,d.ts}");
